select private.seed_lang_examples('pt', 'pt', $doc${"official":{"display_name":"PinWith Oficial","bio":"Listas feitas pela equipe do PinWith."},"samples":[{"display_name":"Usuário de exemplo 1","bio":"Conta de exemplo criada pelo PinWith para mostrar como amigos planejam uma viagem juntos."},{"display_name":"Usuário de exemplo 2","bio":"Conta de exemplo criada pelo PinWith para mostrar como amigos planejam uma viagem juntos."},{"display_name":"Usuário de exemplo 3","bio":"Conta de exemplo criada pelo PinWith para mostrar como amigos planejam uma viagem juntos."}],"lists":[{"role":"plain","owner":"official","slug":"rio-classicos-cartao-postal","kind":"course","title":"Rio de Janeiro clássico: do Cristo a Copacabana","desc":"O roteiro de cartão-postal do Rio em ordem: Corcovado de manhã, Pão de Açúcar no fim da tarde e Copacabana pra fechar o dia.","themes":["riodejaneiro","cartaopostal","primeiraviagem","mirantes","praia"],"sections":[{"name":"Manhã no Corcovado","by":"official","items":[{"place_id":"ChIJE7vYrEh_mQARgLvMGQyS7DY","title":"Trem do Corcovado","memo":"Compre o horário do trem com antecedência e prefira os primeiros da manhã, quando o topo costuma estar sem nuvens e menos cheio.","tags":["trem","cosmevelho"],"lat":-22.940581,"lng":-43.198492},{"place_id":"ChIJmfInzSt-mQARwuIuRFLpEtY","title":"Paineiras","memo":"Ponto de embarque das vans oficiais pro Cristo; boa alternativa quando os horários do trem esgotam.","tags":["van","florestadatijuca"],"lat":-22.947726,"lng":-43.217538},{"place_id":"ChIJP6FKmNV_mQAR3gKVAdeEyZ0","title":"Cristo Redentor","memo":"Olhe a previsão e as câmeras ao vivo antes de subir: com neblina não se vê nada. Leve um casaco leve, venta lá em cima.","tags":["mirante","maravilha"],"lat":-22.951916,"lng":-43.210487}]},{"name":"Fim de tarde na Urca","by":"official","items":[{"place_id":"ChIJb2Zx31mBmQARqb7BAbAbQ1o","title":"Bondinho do Pão de Açúcar","memo":"Chegue umas duas horas antes do pôr do sol: a fila da tarde cresce rápido e você ainda faz a parada no Morro da Urca.","tags":["bondinho","praiavermelha"],"lat":-22.951596,"lng":-43.165132},{"place_id":"ChIJRfg5kECAmQARjLS837zXdYA","title":"Pão de Açúcar","memo":"O pôr do sol atrás do Cristo é o momento mais bonito; fique depois pra ver as luzes da cidade acendendo.","tags":["pordosol","mirante"],"lat":-22.949259,"lng":-43.154576}]},{"name":"Noite em Copacabana","by":"official","items":[{"place_id":"ChIJjcvSoaoqmgARWdXJqK93Ik4","title":"Monumento à Princesa Isabel","memo":"Marca o começo de Copacabana no lado do Leme; daqui dá pra caminhar pelo calçadão de ondas até o Posto 6.","tags":["calcadao","leme"],"lat":-22.964925,"lng":-43.173556},{"place_id":"ChIJLRlF9jvVmwARyOR9aub6a9E","title":"Estátua do Drummond","memo":"Sente no banco ao lado do poeta pra foto clássica e termine com um mate gelado e biscoito Globo na areia.","tags":["foto","copacabana"],"lat":-22.984369,"lng":-43.189156}]}],"comments":[]},{"role":"creator","owner":"official","slug":"vlog-floripa-praias","kind":"collection","title":"[Vlog] Floripa de ponta a ponta: as praias que entraram no vídeo","desc":"As praias de Florianópolis que gravei de norte a sul, com o melhor horário pra filmar, onde estacionar e qual trilha vale o suor.","themes":["florianopolis","vlog","praias","trilha","pordosol"],"sections":[{"name":"Norte da Ilha: mar calmo","by":"official","items":[{"place_id":"ChIJ8-s8Id5CJ5URSh7a27hzLSQ","title":"Ponta das Canas","memo":"Mar de lagoa, quase sem onda — no vídeo eu fiz o drone aqui de manhã cedo, antes do vento e dos barcos chegarem.","tags":["marcalmo","drone"],"lat":-27.395676,"lng":-48.433525},{"place_id":"ChIJi9rCj8FCJ5UReZ9KlsO0oe4","title":"Praia da Lagoinha","memo":"Prainha encaixada entre morros, água bem transparente. A luz fica perfeita no fim da tarde, quando o sol bate de lado.","tags":["aguacristalina","fotos"],"lat":-27.389197,"lng":-48.42186}]},{"name":"Leste: Barra e Lagoa","by":"official","items":[{"place_id":"ChIJm1uYGIg_J5URcJKLhvcJ2s4","title":"Barra da Lagoa","memo":"Vila de pescadores com o canal da lagoa encontrando o mar; filmei os barquinhos coloridos logo cedo, com o mar ainda espelhado.","tags":["pescadores","familia"],"lat":-27.573908,"lng":-48.423923},{"place_id":"ChIJR4ZptEc-J5URdOOD3wCxZhw","title":"Prainha da Barra","memo":"Atravesse a ponte pênsil sobre o canal e siga a trilhinha curta: as piscinas naturais rendem as melhores tomadas da Barra.","tags":["piscinasnaturais","trilhacurta"],"lat":-27.574225,"lng":-48.421067},{"place_id":"ChIJ6xd4cl4_J5URaMCMflTG_DA","title":"Costa da Lagoa","memo":"Só se chega de barco ou trilha — vá de barco pela Lagoa da Conceição e grave a travessia; almoce frutos do mar e volte antes do último barco.","tags":["barco","semcarro"],"lat":-27.543012,"lng":-48.46018}]},{"name":"Sul: trilhas e praia selvagem","by":"official","items":[{"place_id":"ChIJSbuCCWkkJ5URixoTTpM1dkg","title":"Trilha Matadeiro–Lagoinha do Leste","memo":"Trilha pela costeira com vistas o caminho inteiro; leve muita água, tênis com aderência e evite depois de chuva, as pedras ficam lisas.","tags":["trilha","nivelmedio"],"lat":-27.757664,"lng":-48.496067},{"place_id":"ChIJHYPD6AQkJ5URUNqrQOinmK4","title":"Lagoinha do Leste","memo":"A cena mais bonita do vídeo: suba o Morro da Coroa no canto da praia pra ver a lagoa e o mar no mesmo enquadramento.","tags":["selvagem","mirante"],"lat":-27.77321,"lng":-48.486381},{"place_id":"ChIJcSbx_80lJ5URkIooqv17vGc","title":"Praia dos Açores","memo":"Areia branca e pouca gente fora da temporada; ótima pra fechar o dia com o pôr do sol depois da trilha.","tags":["pordosol","tranquila"],"lat":-27.783714,"lng":-48.523675}]}],"comments":[]},{"role":"friends","owner":"ex1","slug":"lisboa-4-dias-com-amigos","kind":"collection","title":"Lisboa em 4 dias com a galera","desc":"Cada um colocou os lugares que quer conhecer e a gente decidiu o roteiro conversando. O plano final está nos comentários da Praça do Comércio.","themes":["lisboa","portugal","viagemcomamigos","europa"],"sections":[{"name":"Alfama do ex1","by":"ex1","items":[{"place_id":"ChIJx-Rwl4QzGQ0RaSfN7SE7IEE","title":"Miradouro de Santa Luzia","memo":"Vista dos telhados de Alfama e do Tejo, com os azulejos do mirante. Quero ir no fim da tarde.","tags":["mirante","azulejos"],"lat":38.711696,"lng":-9.130197},{"place_id":"ChIJk-u706A1GQ0RDFz40CSEuSo","title":"Largo do Chafariz de Dentro","memo":"Começo bom pra se perder nas ruelas de Alfama; à noite tem casas de fado aqui perto.","tags":["fado","ruelas"],"lat":38.711244,"lng":-9.128051},{"place_id":"ChIJbyCqvM8zGQ0R8NBAZs_9Fcw","title":"Feira da Ladra","memo":"Feira de antiguidades e tralhas ao lado do Panteão, só às terças e sábados de manhã.","tags":["feira","antiguidades"],"lat":38.715248,"lng":-9.126207}]},{"name":"Baixa e comilança do ex2","by":"ex2","items":[{"place_id":"ChIJY0ulMHo0GQ0RROAoa18vUzA","title":"Praça do Comércio","memo":"A praça na beira do Tejo com o Arco da Rua Augusta; daqui saem os elétricos pra Belém.","tags":["centro","pontodeencontro"],"lat":38.707283,"lng":-9.136361},{"place_id":"ChIJVZYBfIczGQ0RFFaStJaOGCY","title":"Mercado da Baixa","memo":"Feira de comidas e vinhos na Praça da Figueira em alguns fins de semana; bom pra provar queijo e enchido.","tags":["petiscos","vinho"],"lat":38.713579,"lng":-9.137691},{"place_id":"ChIJdWBeWYc0GQ0RktxySU7hjxM","title":"Time Out Market","memo":"Mercado da Ribeira com várias bancas de chefs; cada um escolhe o seu e a gente divide a mesa.","tags":["comida","cais-do-sodre"],"lat":38.707061,"lng":-9.145669}]},{"name":"Belém do ex3","by":"ex3","items":[{"place_id":"ChIJS5zCw0LLHg0RP1FSz63cAjA","title":"Torre de Belém","memo":"Símbolo de Lisboa na beira do rio; mesmo sem entrar, a foto de fora já vale.","tags":["monumento","historia"],"lat":38.691584,"lng":-9.215977},{"place_id":"ChIJbTeEbWnLHg0RfWB5dNodg10","title":"Jardim da Torre de Belém","memo":"Gramado na frente da torre, bom pra sentar e descansar depois de andar Belém inteira.","tags":["jardim","piquenique"],"lat":38.69287,"lng":-9.215892}]}],"comments":[{"place_id":"ChIJbyCqvM8zGQ0R8NBAZs_9Fcw","by":"ex1","body":"Gente, a Feira da Ladra só rola terça e sábado. A gente chega quinta, então só dá no sábado de manhã, topam?","replies":[{"by":"ex2","body":"Topo, mas cedo, que depois das 11h dizem que fica lotado e com sol forte."},{"by":"ex3","body":"Fechado. E de lá dá pra descer andando pra Alfama, fica tudo pertinho."}]},{"place_id":"ChIJx-Rwl4QzGQ0RaSfN7SE7IEE","by":"ex3","body":"Pra chegar no Santa Luzia vamos de elétrico 28? Vi que a fila é enorme.","replies":[{"by":"ex1","body":"Melhor subir a pé desde a Baixa, uns 20 minutos de ladeira. O 28 a gente pega outro dia bem cedo só pela experiência."}]},{"place_id":"ChIJS5zCw0LLHg0RP1FSz63cAjA","by":"ex3","body":"Belém merece meio dia inteiro: torre, jardim e fila do pastel de Belém. Sexta de manhã?","replies":[{"by":"ex2","body":"Sexta tá previsão de chuva só à tarde, então manhã é perfeito."},{"by":"ex1","body":"Vamos de elétrico 15 saindo da Praça do Comércio, leva uns 30 minutos. Usa o mesmo cartão recarregável do metrô."}]},{"place_id":"ChIJdWBeWYc0GQ0RktxySU7hjxM","by":"ex2","body":"Proposta: jantar no Time Out Market na sexta pra não gastar muito, cada um paga o seu prato.","replies":[{"by":"ex3","body":"Boa, e o Cais do Sodré é do lado, dá pra esticar depois."},{"by":"ex1","body":"Só não vamos no horário de pico, senão não acha mesa pra três. Umas 19h?"}]},{"place_id":"ChIJY0ulMHo0GQ0RROAoa18vUzA","by":"ex1","body":"Plano final! Qui: chegada, Baixa e pôr do sol no Santa Luzia. Sex: Belém de manhã (elétrico 15 daqui), tarde livre e Time Out às 19h. Sáb: Feira da Ladra cedo, Alfama a pé e fado à noite perto do Chafariz de Dentro. Dom: Mercado da Baixa se tiver e volta. Ponto de encontro sempre aqui no Arco.","replies":[{"by":"ex2","body":"Perfeito, vou reservar o fado de sábado."},{"by":"ex3","body":"Aprovado! Vou baixar os mapas offline de Lisboa no celular de todo mundo."}]}]},{"role":"food","owner":"official","slug":"sp-mercadao-classicos","kind":"collection","title":"Clássicos do Mercadão de São Paulo","desc":"O roteiro de comer no Mercado Municipal: do sanduíche de mortadela ao pastel de bacalhau, com onde sentar pra almoçar e o que levar pra casa.","themes":["saopaulo","mercadao","comidadeboteco","mortadela","centro"],"sections":[{"name":"Os ícones do Mercadão","by":"official","items":[{"place_id":"ChIJBQICYYxfzpQR9P4GxnTkmgA","title":"Mercadão","memo":"Vá em dia de semana de manhã pra fugir da muvuca de sábado e repare nos vitrais do salão principal.","tags":["historico","vitrais"],"lat":-23.542022,"lng":-46.629411},{"place_id":"ChIJYzoU1PhYzpQRjmYsKF9otzI","title":"Bar do Mané","memo":"O sanduíche de mortadela gigante é pra dividir — um dá tranquilamente pra duas pessoas.","tags":["mortadela","pradividir"],"lat":-23.541572,"lng":-46.629487},{"place_id":"ChIJMziy0_hYzpQRuGahR8G4KWk","title":"Hocca Bar","memo":"Fica no mezanino; peça o pastel de bacalhau, a fila anda rápido.","tags":["pastel","bacalhau"],"lat":-23.541766,"lng":-46.629394},{"place_id":"ChIJnwmKKv9YzpQR1QrwlnRZWlM","title":"Tigrão Lanchonete","memo":"Boa opção quando os famosos estão lotados: pastel e lanche no balcão sem enrolação.","tags":["pastel","balcao"],"lat":-23.542823,"lng":-46.629712}]},{"name":"Pra sentar e almoçar","by":"official","items":[{"place_id":"ChIJ_cjIR0RZzpQR3vhXoTXZ0LM","title":"Picanharia Mercadão","memo":"Pra quem quer prato de verdade: picanha na chapa com acompanhamentos, ótimo pra grupo.","tags":["carne","almoco"],"lat":-23.541962,"lng":-46.629208},{"place_id":"ChIJiXYjzQBZzpQRmp10UVy4hGw","title":"Hunico","memo":"Mesa no mezanino com vista pro movimento do mercado; bom pra um drink depois de comer.","tags":["drinks","mezanino"],"lat":-23.541819,"lng":-46.629386},{"place_id":"ChIJd7rTtIBZzpQRFUvV_dMWiV4","title":"O Espanhol","memo":"Tapas e frutos do mar pra variar do pastel e da mortadela.","tags":["tapas","frutosdomar"],"lat":-23.541819,"lng":-46.629386}]},{"name":"Lanche e saideira","by":"official","items":[{"place_id":"ChIJ7VjA0_hYzpQRpsPfGpt-i9E","title":"Padaria Paulistana","memo":"Pão na chapa e pingado no balcão, do jeito paulistano, pra começar o passeio.","tags":["cafe","padaria"],"lat":-23.541819,"lng":-46.629386},{"place_id":"ChIJ3c-rPclZzpQRdUog-SBZE1Q","title":"Delícias da Pérsia","memo":"Shawarma e doces árabes, lembrança da forte imigração sírio-libanesa da região da 25 de Março.","tags":["arabe","doces"],"lat":-23.541344,"lng":-46.629235}]}],"comments":[]}]}$doc$::jsonb);
